import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易集說卷一","description":"周易集說 - 周易集說卷一","frontmatter":{"title":"周易集說卷一","description":"周易集說 - 周易集說卷一"},"headers":[],"relativePath":"classics/jishuo/002.md","filePath":"classics/jishuo/002.md"}'),r={name:"classics/jishuo/002.md"};function i(o,p,c,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易集說卷一" tabindex="-1">周易集說卷一 <a class="header-anchor" href="#周易集說卷一" aria-label="Permalink to “周易集說卷一”">​</a></h1><p>欽定四庫全書</p><p>宋俞琰撰。</p><p>周，代名；易，書名。猶周書題周以別於夏、殷也。易有二義，變易也，交易也。變易者，陽變陰，陰變陽也；交易者，陽交陰，陰交陽也。觀先天圖，可見經即篇也。孔子稱乾坤之策曰「二篇」，則「經」字乃後人所加。呂東萊謂「經分上下，必始於文王」，郭白雲謂「序卦已分，其來尚矣」，皆不言分經之由。邵康節曰：「重卦之象，不易者八，反易者二十八，故卦有六十四，而用止乎二百一十有六。」知此，則知經之所以分上下者，蓋有由焉，非苟然也。或疑上經卦三十，下經卦三十四，多寡不均。殊不知卦有對體，有覆體。何謂覆體？屯倒轉為蒙，需倒轉為訟之類是也。何謂對體？乾、坤、坎、離、頤、大過、中孚、小過，相對而不可覆者是也。餘皆一卦倒轉為兩卦，故上經卦三十，約之則十八，下經卦三十四，約之亦十八，謂之不均可乎？卦分內外二體，凡六十四陽、六十四陰，約為三十六，則上經純陽卦六，純陰卦四；下經純陽卦四，純陰卦六。陰陽相重之卦，上下經皆八，不亦均乎？上經陽爻八十六，陰爻九十四，約為十八，則五十二陽、五十六陰，共一百八。下經陽爻一百六，陰爻九十八，約為十八，則五十六陽、五十二陰，亦一百八。其均如此。孔穎達謂，繋辭分上下，無異義，直以簡帙重大，是以分之。晁以道乃曰：「古者竹簡重大，分經為二篇。」今又何必以二篇成帙？蓋皆不知六十四卦，約之則為兩十八也。䷀ 乾下乾上 「乾」：元亨利貞。</p><p>「乾」，健也。畫奇屬陽而體剛，故其性健。此卦「乾」下「乾」上，而六畫之奇，純乎陽，剛健之至也。「元」，大也。「亨」，通也。「利」，宜也。「貞」，正而固也。其佔為始雖大通，又宜固守以正，然後可保其終。蓋不可恃其至健而妄動也。初九：潛龍勿用。</p><p>「初」，即一之異名。卦畫自下而上，故以一為初。「一」言初，則六為終；「六」言上，則一為下。互文相通也。「九」，陽數。「潛」，藏也。「龍」，大而靈變之物，以象「乾」六爻之變也。「勿」，禁止之辭。「用」，謂動而施為。初九在下「乾」之下，陽氣潛藏，故其象為「潛龍」。潛則隱而未見，故其佔為君子「勿用」。九二，見龍在田，利見大人。</p><p>「田」，地上也。龍之出見而在田，猶君子出仕而在位也。「大人」，有大德之人也。九二在下「乾」之中，乃陽氣發見於地上之時，故其象為「見龍在田」，其佔為「利見在下」之「大人」。「見龍」之「見」，音現。「利見」之「見」，如字。</p><p>九三，君子終日乾乾，夕惕若，厲無咎。</p><p>六爻皆君子也。此爻居天田之間，正當人位，故特稱「君子」以發之。在下「乾」之終，故曰「終日」。下「乾」終而上「乾」繼之，故曰「乾乾」。「夕」，日之過中也。「惕」，懼也。「若」，助語。九三處重乾之交，而自強不息，又因日之過中，省察自己之不中而兢兢焉，故其象如此。「厲」，危而不安也。「咎」，譴責也。夫以九居三，剛而不中，居下之上，乃危地也。其佔何以「無咎」？曰：君子「終日乾乾」，至於日之夕而猶惕懼，故雖危厲，亦「無咎」也。「夕惕若」為句，「厲無咎」為句。</p><p>九四，或躍在淵，無咎。</p><p>「或」，疑辭，謂其在兩「乾」之間，而或上或下也。「淵」，深水，龍之所居也。九四亦剛而不中者也，離地而躍於人之上，能「無咎」乎？所以「無咎」者，躍而在淵，處卑而不犯上也。「乾」六爻雖皆君德，以位言，則唯五為君，餘皆臣也。九四爻剛位柔，以臣近君，以淵近天，故其象佔如此。</p><p>九五，飛龍在天，利見大人。</p><p>九五，君位之至尊，猶天之不可階而升也，故其象為龍之飛而在天，其佔為利見在上之大人。上九，亢龍，有悔。亢，口浪反。極甚之為「亢」。上九過中而居「乾」終，六陽之窮，故其象為「亢龍」。「悔」，懊恨也。有過則有悔。上九位高而不知退，動極而不知止，故其佔曰「有悔」。</p><p>用九，見群龍無首，吉。</p><p>筮法：陽數窮於九，陰數窮於六，窮則必變。「乾」爻用九，坤爻用六，蓋取其變也。「見」，如字。「見群龍無首」為句。「乾」為首，「乾」六爻皆九，則變而為「坤」，是為「群龍無首」之象。「吉」，善也。佔者見此象而處後則善，不可為首也。剛太過則折，非善道也，故「上九，亢龍有悔」。六陽變為六陰，則剛而能柔，吉之道也，故</p><p>「用九，見群龍無首，吉」。䷁ 坤下坤上</p><p>「坤」，元亨，利牝馬之貞。君子有攸往，先迷，後得主，利。西南得朋，東北喪朋。安貞吉。</p><p>「坤」，順也。畫偶屬陰而體柔，故其性順。此卦「坤」下「坤」上，而六畫之偶純乎陰，柔順之至也。「坤」順「乾」之健，故其佔亦為「元亨」。北地馬群，每十牝隨一牡而行，不入它群，是為「牝馬之貞」。坤道以陰從陽，其貞如牝馬之從牡，則利，故曰「利牝馬之貞」。易中凡稱君子，皆指佔者而言。「有攸往」，謂有所行也。「坤」從「乾」而行，先乎「乾」則迷而失道，後乎「乾」則得「乾」為主而利。故曰「君子有攸往，先迷，後得主，利」。「朋」，坤類也。「西南」，「坤」之本方。「兌」、「離」、「巽」皆「坤」類，是為「得朋」。出而從乾，則東北震、艮、坎非坤類，是為「喪朋」。君子之出處，隨寓能安，壹是皆以貞自持，蓋無往而不吉，故曰：「西南得朋，東北喪朋，安貞吉。」初六，履霜，堅冰至。</p><p>「六」，陰數。「霜」，陰氣之始凝也。坤初而言「履霜堅冰至」，以象小人惡跡，始雖甚微，如霜之在地，盛而與君子為敵，則如冰之堅固也。「至」，謂馴致其道，必至於此極也。</p><p>六二，直方大，不習無不利。</p><p>以六居二，得坤道之正，又在坤道之中。正則無私無曲，中則無偏無黨，是以執直而不回，執方而不移也。易以陽為大，陰為小，六二陰小而稱大，何也？曰：從乾也。從乾而行，則大也。「習」，與書太甲篇「習與性成」之「習」同。「不習」，謂六二中正，不與初六不中不正之朋相習為不善也。擇善而得所從，則不疑其所行，故「無不利」。</p><p>六三，含章可貞，或從王事，無成有終。</p><p>以六居三，陰中有陽，故曰「含章」，謂其有美而不露於外也。「可貞」，謂當其可而貞，非純乎固執也。「或」，疑辭，謂非必也。「從王事」，謂從乾君之事。坤道固宜靜而有守，或有王事，則動而從之，弗違也。「無成」，謂持美以歸於君，不居其成功也。「有終」，謂職分居此，則當終其勞也。六三爻柔位剛，而在下體之終，故其象佔如此。</p><p>六四，括囊，無咎無譽。</p><p>「咎」，致罪；「譽」，致疑。唯能謹密如囊口之結括，則「無咎無譽」。六四爻位俱柔，而近六五，故其象佔如此。六五，黃裳，元吉。</p><p>「黃」，中色；「裳」，下服。「坤」之從乾，猶裳之承衣也。六五柔順而得中，降尊而處卑，故其象如此，其佔為大善之吉。坤六爻皆臣道，「坤」之六五，其位雖君，其道則臣，故不言「黃衣」，而言「黃裳」。蓋唯「黃裳」則「元吉」，不「黃裳」則大凶。</p><p>上六，龍戰於野，其血玄黃。</p><p>上六居坤終，六陰之窮，陰盛而與陽對敵，故其象為龍之戰鬥。「野」，外也。在外卦之外，故言「野」。「血」，傷也。「玄黃」者，陰陽之雜也。戰而兩敗俱傷，故曰「其血玄黃」。用六：利永貞。</p><p>筮法體七、八而用九、六者，七、八少不變，九六老則變也。坤六爻俱六，則變而為「乾」本體，蓋陰柔也。以其陰柔之動，或失於邪，故戒之曰：「利永貞」。「永」，久也。䷂ 震下坎上</p><p>屯，元亨，利貞。勿用有攸往，利建侯。</p><p>屯，張倫反。此卦下震上坎。「震」，動也。「坎」，險也。動而遇險，則其動艱難，而未能遽通，「屯」之義也。處屯之時，不動則不能出險，動則可以大亨。然動乎險中，則宜固守以正，故其佔曰：「元亨，利貞。」蓋總上下二體而言處屯之道也。「勿用有攸往」，指上體之坎，謂坎險在前，不可遽往也。「利建侯」，指下體之震，謂宜建立侯國之君也。</p><p>初九：磐桓，利居貞，利建侯。</p><p>磐，大石也，與漸六二之「磐」同。桓，柱也。禮記檀弓篇所謂「桓楹」是也。橫渠張子曰：「磐桓，猶言柱石。」或以「磐桓」為盤旋徘徊之義，誤矣。「居」，不動也。初九震體好動，故戒之曰：「磐桓，利居貞。」震為長子，以剛德處下，為成卦之主，而有濟屯之才，故以彖辭「利建侯」屬之。此爻凡兩言「利」，當分為兩說。春秋左氏傳雲：「孔成子遇此佔，以示史朝。史朝對曰：各以所利。」蓋「居貞」自是「居貞」之「利」，「建侯」自是「建侯」之「利」，不可紐為一說也。</p><p>六二，屯如邅如，乘馬班如，匪寇，婚媾。女子貞不字，十年乃字。</p><p>邅，張連反，難行不進之貌。「乘」，當依項平庵按陸德明釋文作繩證反。四馬曰「乘」。班，分佈貌，與春秋左氏傳「班荊」之「班」同。「如」，助語。六二雖是震體之動，然非動之主，況其才柔弱，豈能濟屯？所以「屯如邅如，乘馬班如」者，待初九之動而後動也。五，坎體之盜，故言「寇」。與二正應，則「匪寇」矣，乃「婚媾」也。六二陰柔，故稱「女子」。曲禮雲：「女子許嫁，笄而字。」字以代名也。今曰「女子貞不字」者，以初九近而見逼，故未可字也。「十年乃字」者，十年之後，初既求四為婚媾，則彼自得偶，無復見逼，然後可以字也。婚媾而「十年乃字」，此亦屯道艱難，而未能遽通之義。夫「屯如邅如」、「乘馬班如」，自是一說。「匪寇，婚媾，女子貞不字，十年乃字」，又自是一說。易中多有一爻而取兩象者，皆當分為兩說，混而為一，則鑿矣。</p><p>六三，即鹿無虞，惟入於林中。君子幾，不如舍，往吝。「即」，就也。「鹿」，指五。「無虞」，謂無應也。書舜典雲：「諮益，汝作朕虞。」孔安國雲：「掌山澤之官。」周禮有「山虞」。鄭玄雲：「虞，度也。度知山林之大小及所生者。」「幾」，音機，近也。「舍」，武夜反，止也。「幾」，謂時位至於六三，則當盡其才力，不可不及也。「舍」，謂職分終於六三，則又當量其才力，不可過也。「吝」，恨惜也。六三才柔而志剛，蓋欲往濟九五之屯，而上無應援，猶即鹿而無虞人引導，故雖入於林中，不若止而弗往，往則俱陷，徒恨惜也。「君子」，指佔者而言。三居下體震動之極，而互艮止，故其象佔如此。「惟」，當作「雖」，與豐初九「雖旬無咎」之「雖」同。</p><p>六四：乘馬班如，求婚媾，往，吉，無不利。</p><p>六四言「乘馬班如」，是亦有志於濟屯，而其才不逮者也。初來求四，四往應初，得「婚媾」之正，故「吉」而「無不利」。九五：屯其膏，小貞吉，大貞兇。</p><p>九五正陷於「坎」險之中，而膏澤不下於民，故其象為「屯其膏」。處屯之時，與常時不同，唯能退託不明，而以謙小自守，則「吉」。若以尊大自居，固執而不知變，則「兇」。故其佔曰：「小貞吉，大貞兇。」</p><p>上六：乘馬班如，泣血漣如。</p><p>二比初，四應初，俱言「乘馬班如」，蓋皆待其動而後動也。上與初非應非比，亦言「乘馬班如」，何所待而然耶？曰：上與三、四皆有濟屯之志，而無其才者也。既不能自動，而又居屯之窮，唯有憂懼而「泣血漣如」，故其象如此。其佔不言「兇」者，時勢使然，非其罪也。䷃ 坎下艮上</p><p>蒙，亨。匪我求童蒙，童蒙求我。初筮告，再三瀆，瀆則不告。利貞。</p><p>「蒙」，與書伊訓「蒙士」之「蒙」同。內險而不自安，外止而不能動，蒙之義也。「亨」以下，佔辭也。九二以剛德居中，能啟群陰之「蒙」，故蒙有亨通之道焉。「我」，指二。「童蒙」，指五。五，君也，「蒙」之主也。乃主二而稱「我」，何也？曰：五在六十四卦中，乃定位之主；二在蒙，乃成卦之主，蓋一時得權者也。曲禮雲：「禮聞來學，不聞往教。」「蒙」，六五以柔德居中，虛己以求二，非二往求於五，故曰「匪我求童蒙，童蒙求我」。「筮」者，揲蓍叩神以決疑也。「初筮」，指九二。「再三」，指上九。「告」，如字。「三」，去聲。「瀆」，與少儀「毋瀆神」之「瀆」同。「不告」，與詩小旻「我龜既厭，不我告猶」之義同。初筮則其志專一，故「告」；再、三則煩瀆，故「不告」。蓋童蒙之求師，與人之求神，其道一也。「貞」，正也。二、五皆不正，故戒之曰「利貞」。</p><p>初六：發矇，利用刑人，用說桎梏。以往，吝。「發矇」，教之於初也。教之弗聽，則刑之宜也。若不施鞭撲，遽說其桎梏，縱之使往，必待其罪大惡極而後擊之，雖恨惜亦無及矣。「說」，音脫。「桎梏」，刑具。此爻凡兩言用，善用之則利，不善用之則吝也。九二，包蒙，吉；納婦，吉；子克家。</p><p>此爻凡兩言「吉」，「包蒙」之「吉」，謂包初六在下者之蒙也。「納婦」之吉，謂納六三近比之陰柔也。</p><p>九二剛得中而無過，故為「包蒙」、「納婦」皆吉。以剛處內，而上與六五之柔相應，故又為「子克家」之象。「克家」，能治其家也。</p><p>六三，勿用取女，見金夫，不有躬，無攸利。</p><p>取，音娶。「金夫」，指九二之剛。六三陰柔，不正不中，不可取也。舍上九之應，而近唯九二之從，此女子見金夫而不有其躬者也。其象如此，故其佔為「無攸利」。六四，困蒙，吝。</p><p>六四與九二、上九相遠，「困」而不學，是可恨惜也。純乎陰柔，而乘應亦皆陰柔，故其象佔如此。六五，童蒙，吉。</p><p>「蒙」之六五，以陰柔之小而居尊位，此「童蒙」之君也。能下求九二剛陽之助，故「吉」。</p><p>上九：擊蒙，不利為寇，利禦寇。上九乃蒙極而怙終者也，其罪當擊，故曰「擊蒙」。「為」，當，依王晦叔作去聲，與論語「為衛君乎」之「為」同。「寇」，指六三坎體之盜。上九而下與之應，則不利，處乎上而拒之，則利，故曰「不利為寇，利禦寇」。䷄ 乾下坎上</p><p>「需」，有孚，光亨，貞吉，利涉大川。</p><p>「需」，待也。乾健而遇坎險，則未能上進，「需」之義也。「需」以五為成卦之主爻。「有孚，光亨，貞吉」，皆指五。「孚」，信也。九五與九二同德相信，是為「有孚」。陽明而光，故「亨」。固守以正而不妄動，故「吉」。坎水之險在前，「乾」以剛健臨之，而又能「需」，則不至乎陷溺，故其象佔為「利涉大川」。</p><p>初九：需於郊，利用恆，無咎。</p><p>爾雅雲：「邑外謂之郊。」「郊」乃近邑之地也。易以中爻為邑，初、上為郊，初近二，故言「郊」。「恆」，久也。「需於郊」，雖去坎水遠，亦不宜輕動，故其佔為「利用恆」，然後可以「無咎」。</p><p>九二，需於沙，小有言，終吉。「沙」與「泥」相連，則稍近坎水之險矣。「需」於此，雖小有言語之相侵，然九二剛而得中，不急於進，故亦「終吉」。</p><p>九三，需於泥，致寇至。</p><p>「泥比沙」，則逼於坎水之險矣。九三過剛不中，非能「需」者也，故「致寇至」。</p><p>六四，需於血，出自穴。</p><p>「血」，傷也。三陽自下而進，四當避之，「需」於此而不避，必見傷矣。六四純乎柔順者也，故能釋位而去，以聽三陽之進，則彼自來，我自出，兩無傷也。「穴」，乃陰虛之地，六四陰爻之虛，故言「穴」。</p><p>九五，需於酒食，貞吉。</p><p>「酒食」者，需客之具，所以待三陽之來也。唯能固守以正而不亂，則吉，故曰：「需於酒食，貞吉。」五為「需」主，故以彖辭「貞吉」屬之。</p><p>上六，入於穴，有不速之客三人來，敬之，終吉。</p><p>上六「需」極，故不言「需」。陰爻之虛，故其象亦為「穴」。倒轉為「訟」，則穴在下，故曰「入於穴」。三陽皆進而在上，非己所召，有不速之客三人來之象。詩伐木雲：「以速諸父。」鄭玄雲：「速，召也。」「需」既極矣，故三客不待召而自來。柔不可以敵剛，寡不可以敵眾，故戒之曰：「敬之終吉。」周易集說卷一，</p>',64)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
